import{_ as t,l as i,o as a,c as n,v as o,p as d,x as l,d as p,i as P,S as s}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"移动端 NPU 部署","description":"","frontmatter":{"title":"移动端 NPU 部署","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mobile-npu-deploy.md","filePath":"llm/mobile-npu-deploy.md","lastUpdated":1789023840000}'),c={name:"llm/mobile-npu-deploy.md"};function N(h,e,E,m,u,A){const r=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="移动端-npu-部署" tabindex="-1">移动端 NPU 部署 <a class="header-anchor" href="#移动端-npu-部署" aria-label="Permalink to &quot;移动端 NPU 部署&quot;">​</a></h1><div class="epigraph"><p>手机上的 TOPS 写在发布会上；LLM decode 要的是能持续吃带宽的矩阵核、以及不会把 8GB DRAM 吃光的 KV 预算。</p><footer>—— 对照 ExecuTorch / Core ML / NNAPI / 厂商 QNN 的端侧部署栈；量化与内存是硬约束</footer></div><p><a href="/llm/webgpu-inference">上一课</a>是浏览器沙箱。原生 App 可以走 NPU：Apple Neural Engine、高通 Hexagon、联发科 APU，经由 Core ML、NNAPI、QNN、ExecuTorch。本课写部署差：静态图编译、INT8/INT4、热包络、以及 decode 循环往往仍落在 CPU/GPU，因为 NPU 对动态 KV 不友好。不要把「设备有 45 TOPS」写成「70B 能跑」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NPU 喜欢固定形状卷积/GEMM。LLM 逐步 \\(n\\) 变、采样不规则、投机分支，编译器要么 pad 到 \\(n_{\\max}\\)（DRAM 炸），要么每步回 CPU。缺口是混合：投影与 FFN 下沉 NPU，注意力在 GPU/CPU；或整网 CPU 量化（llama.cpp 系）。热功耗：持续 decode 会降频，峰值 TOPS 与持续 token/s 不是一回事——<a href="/llm/energy-per-token">每 token 能耗</a>在手机上直接决定能不能聊完一条消息。</p><p>后台：OS 会杀长时间 GPU/NPU 占用。产品要把生成切成可暂停步。</p><p><span class="marginnote">ExecuTorch 把 PyTorch 边下沉边解释；Core ML 转换对动态控制流不完整。选栈先看 generate 循环能不能留下，再看算子覆盖。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型级：1B–8B 级量化，上下文 2K–8K 量级起步。KV 用量化或短窗。工具链：能导出的静态子图下 NPU，循环在运行时。与分词：移动端分词必须 C++/Rust，不能起 Python。UI 流式走稳定前缀。电量：测持续功率，不是芯片海报。</p>',9)),(a(),d(s,null,{default:l(()=>[P(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20Q%5B%22INT8%2FINT4%20%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20Q%20--%3E%20SPLIT%5B%22%E9%9D%99%E6%80%81%E5%AD%90%E5%9B%BE%20%E2%86%92%20NPU%22%5D%0A%20%20Q%20--%3E%20LOOP%5B%22%E9%80%90%E6%AD%A5%E5%BE%AA%E7%8E%AF%E5%9C%A8%20CPU%2FGPU%22%5D%0A%20%20LOOP%20--%3E%20KV%5B%22%E7%9F%AD%E4%B8%8A%E4%B8%8B%E6%96%87%20%2F%20%E9%87%8F%E5%8C%96%20KV%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>屋顶线：NPU 峰值高、能用的形状窄；decode 强度低，可能根本打不满 TOPS，瓶颈回到 DRAM。这与数据中心 decode 同构，只是绝对数字更差。厂商 SDK 的「LLM 方案」往往是自家核 + 私有格式，可移植性低于 ONNX。选择等于绑定 SoC。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在 NPU 上假设任意 <a href="/llm/logit-bias">logit bias</a> 与文法掩码都能融合。不要用峰值 TOPS 除以 FLOPs 估 TPOT。下一课：纯 CPU 量化路径，反而更可移植。</p><p>出处：ExecuTorch；Core ML；NNAPI；厂商 QNN 文档。不发明 arXiv。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>手机 NPU 适合静态子图；LLM decode 循环常留在 CPU/GPU。</li><li>峰值 TOPS ≠ 持续 token/s；热与 DRAM 是真约束。</li><li>模型要小、KV 要短、权重要量化。</li><li>分词与 generate 必须在原生运行时。</li><li>SoC SDK 绑定与可移植性权衡。</li><li>下一课：CPU 推理与量化。</li><li>出处：ExecuTorch；Core ML；NNAPI。</li></ul>',7))])}const U=t(c,[["render",N]]);export{_ as __pageData,U as default};
